import { COURSE, EXAMPLES, QUESTIONS, PHASES } from './data.js';
import { store, storageAvailable } from './store.js';
import { icon, graph, escapeHTML as e } from './ui.js';
export const NAV = [{id:'overview',label:'学习总览',icon:'grid'},{id:'resources',label:'课程资料',icon:'book'},{id:'chat',label:'学习问答',icon:'chat'},{id:'practice',label:'练习复习',icon:'practice'},{id:'roadmap',label:'开发路线图',icon:'route'}];
const badge = (text,cls='muted')=>`<span class="badge ${cls}">${text}</span>`;
const link = (href,label,cls='secondary',symbol='arrow')=>`<a class="btn ${cls}" href="#/${href}">${label}${icon(symbol)}</a>`;
export function heading(eyebrow,title,description,actions='') { return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`; }
export function localNotice() { return !storageAvailable ? '<div class="callout warning">当前浏览器存储不可用，修改仅保留到本次页面关闭。请及时导出。</div>' : ''; }
export function unresolved() { const last=new Map(); for(const a of store.attempts)last.set(a.questionId,a); return [...last.values()].filter(a=>!a.correct); }
export function overview() {
  const own=store.notes.filter(n=>!n.sample).length, attempts=store.attempts, correct=attempts.filter(a=>a.correct).length;
  return `${heading('YOUR LEARNING, CONNECTED','让每一个问题，都有下一步。','从数据结构开始，建立属于你的知识、练习与思考空间。',`<button class="btn secondary" data-action="new-note">${icon('plus')}添加笔记</button>`)}${localNotice()}
  <div class="welcome-grid"><section class="hero-card"><div class="hero-copy"><p class="hero-kicker"><span class="live-dot"></span>从第一门课程开始</p><h2>把零散的知识，<br>学成自己的体系。</h2><p>带着问题读资料，用练习检验理解。<br>先学懂一个概念，再向前多走一步。</p><div class="hero-actions">${link('chat','开始示例问答','primary')}${link('resources','浏览课程资料','ghost','book')}</div><div class="hero-footer"><span>${icon('link')}答案可追溯来源</span><span>${icon('layers')}学习记录留在本地</span></div></div><div class="hero-decoration" aria-hidden="true"><span class="deco-label">LEARN<br>BY ASKING.</span><div class="deco-orbit orbit-one"></div><div class="deco-orbit orbit-two"></div><span class="deco-dot"></span></div></section>
  <section class="focus-card"><div class="panel-heading"><span class="section-kicker">一个值得想明白的问题</span>${badge('课程示例','green')}</div><h3>BFS 为什么能找到<br>无权图的最短路径？</h3>${graph()}<div class="focus-footer"><span>图与遍历 <span class="muted">/</span> 广度优先搜索</span><button class="icon-btn" data-example="bfs" aria-label="查看 BFS 示例问答">${icon('arrow')}</button></div></section></div>
  <div class="stats-row"><div class="stat-card"><span class="stat-icon">${icon('book')}</span><div><div class="stat-value">${String(own).padStart(2,'0')}<span>份</span></div><span class="stat-label">我的课程笔记</span><p class="stat-note">另有 3 份自写示例资料</p></div></div><div class="stat-card"><span class="stat-icon coral">${icon('chat')}</span><div><div class="stat-value">${String(store.conversations.length).padStart(2,'0')}<span>次</span></div><span class="stat-label">已记录的问题</span><p class="stat-note">当前为预置问答演示</p></div></div><div class="stat-card"><span class="stat-icon sand">${icon('practice')}</span><div><div class="stat-value">${String(attempts.length).padStart(2,'0')}<span>次</span></div><span class="stat-label">练习提交</span><p class="stat-note">${attempts.length?`答对 ${correct} 次 · 待复习 ${unresolved().length} 题`:'做一道题，检验自己的理解'}</p></div></div></div>
  <div class="dashboard-grid"><section class="panel"><div class="section-heading"><div><p class="section-kicker">YOUR KNOWLEDGE BASE</p><h2>从这些资料开始</h2></div><a class="text-link" href="#/resources">全部资料 ${icon('arrow')}</a></div><div class="resource-list">${store.notes.slice(0,3).map(n=>`<button class="resource-row" data-note="${e(n.id)}"><span class="file-icon">${icon('file')}</span><span class="resource-info"><strong>${e(n.title)}</strong><small>${e(n.category)} · ${n.sample?'知序自写示例':'我的笔记'}</small></span><span class="tag">${n.sample?'示例':'本地'}</span><span class="row-action">${icon('diagonal')}</span></button>`).join('')}</div></section>
  <section class="panel getting-started"><div class="section-heading"><div><p class="section-kicker">A SMALL STEP, EVERY TIME</p><h2>你的第一条学习路径</h2></div><span class="tiny-pill">3 步开始</span></div><ol class="steps-list"><li class="step-item"><span class="step-number">01</span><div class="step-copy"><a href="#/resources">读一份笔记 ${icon('arrow')}</a><p>先从栈、二分查找或 BFS 开始。</p></div></li><li class="step-item"><span class="step-number">02</span><div class="step-copy"><a href="#/chat">问一个具体问题 ${icon('arrow')}</a><p>体验有依据、能回到原文的回答。</p></div></li><li class="step-item"><span class="step-number">03</span><div class="step-copy"><a href="#/practice">用一道题确认理解 ${icon('arrow')}</a><p>提交答案，查看解释并记录错题。</p></div></li></ol></section></div>
  <section class="growth-section"><div class="section-heading"><div><p class="section-kicker">BUILT TO GROW WITH YOU</p><h2>今天的起点，未来的工作台。</h2></div><a href="#/roadmap" class="text-link">查看开发计划 ${icon('arrow')}</a></div><div class="roadmap-strip">${[{n:'01',t:'结构与交互',p:'当前版本 · 搭建学习空间',active:true},{n:'02',t:'真实问答与检索',p:'模型接入 · 原文引用'},{n:'03',t:'练习与个性化',p:'答题反馈 · 复习安排'},{n:'04',t:'代码实战与研究',p:'工具调用 · 对照实验'}].map(m=>`<a href="#/roadmap" class="milestone ${m.active?'current':''}"><span class="milestone-dot">${m.n}</span><span class="milestone-title">${m.t}</span><p>${m.p}</p></a>`).join('')}</div></section>`;
}
export function noteCards(query='') {
  const q=query.trim().toLowerCase();const notes=store.notes.filter(n=>[n.title,n.content,n.category].some(s=>s.toLowerCase().includes(q)));
  if(!notes.length)return '<div class="empty-state">没有找到匹配资料。试试其他关键词，或添加一份自己的笔记。</div>';
  return notes.map(n=>`<article class="note-card"><div class="note-card-top"><span class="file-icon">${icon('file')}</span>${badge(n.sample?'自写示例':'我的笔记',n.sample?'muted':'green')}</div><h3><button data-note="${e(n.id)}">${e(n.title)}</button></h3><p class="note-preview">${e(n.content.replace(/§\d[^\n]*\n/g,'').slice(0,100))}…</p><div class="note-card-bottom"><span class="tag">${e(n.category)}</span><button class="text-link" data-note="${e(n.id)}">阅读 ${icon('arrow')}</button></div></article>`).join('');
}
export function resources() { return `${heading('COURSE MATERIALS','让知识有处安放。','管理课程笔记，先把你真正需要的知识整理起来。',`<button class="btn secondary" data-action="import-note">${icon('download')}导入文本</button><button class="btn primary" data-action="new-note">${icon('plus')}添加笔记</button>`)}${localNotice()}<div class="callout">${icon('layers')}<div><strong>你的个人学习资料库</strong><p>新增内容仅保存在当前浏览器，可随时导出。当前问答使用预置示例，你新增的资料尚未参与 AI 回答。</p></div></div><div class="toolbar"><label class="search-field">${icon('search')}<input id="note-search" type="search" placeholder="搜索标题、内容或知识点" aria-label="搜索课程资料"></label><span class="muted" id="note-count">${store.notes.length} 份资料 · 数据结构与算法</span></div><div class="resource-grid" id="note-grid">${noteCards()}</div><input type="file" id="note-file" accept=".txt,.md,text/plain,text/markdown" hidden>`; }
export function messages() { return store.conversations.map(m=>`<article class="chat-message user"><div class="message-label">你</div><div class="message-body">${e(m.question)}</div></article><article class="chat-message assistant"><div class="message-label">${icon('spark')} 知序 ${badge(m.unsupported?'尚未接入 AI':'预置示例','muted')}</div><div class="message-body">${e(m.answer).replace(/\n/g,'<br>')}</div>${m.sourceId?`<button class="source-link" data-note="${e(m.sourceId)}" data-highlight="${e(m.quote||'')}">${icon('link')}来源：${e(store.getNote(m.sourceId)?.title)} · ${e(m.section)} ${icon('diagonal')}</button>`:''}</article>`).join(''); }
export function chat() { return `${heading('ASK, UNDERSTAND, CONNECT','带着问题，走近答案。','围绕课程资料提问，保留依据，也保留自己的思考。')}${localNotice()}<div class="chat-layout"><section class="chat-main"><div class="chat-demo-banner"><span class="demo-indicator"></span><strong>预置示例演示</strong><span>尚未连接模型 · 不会解答自由问题</span></div><div class="chat-scroll" id="chat-history">${store.conversations.length?messages():`<div class="chat-intro"><span class="intro-mark">${icon('spark')}</span><h2>一个好问题，是理解的开始。</h2><p>点击一个示例，看看回答如何关联原文。<br>你也可以记录自己的问题，留待后续探索。</p><div class="suggestion-list">${EXAMPLES.map((x,i)=>`<button class="suggestion-btn" data-example="${x.id}"><span class="mono">0${i+1}</span>${e(x.question)}${icon('arrow')}</button>`).join('')}</div></div>`}</div><form id="chat-form" class="chat-composer"><label class="sr-only" for="question-input">记录你的学习问题</label><textarea id="question-input" name="question" rows="2" maxlength="2000" placeholder="记录一个问题，或点击示例体验问答…" required></textarea><div class="composer-footer"><span>${icon('book')}数据结构与算法 · 3 份预置示例</span><button type="submit" class="btn primary small">记录问题 ${icon('arrow')}</button></div></form></section><aside class="chat-aside"><section class="panel"><p class="section-kicker">HOW IT WORKS</p><h3>回答，应该有依据。</h3><div class="aside-step"><span>01</span><div><strong>找到相关资料</strong><p>真实检索将在下一阶段接入。</p></div></div><div class="aside-step"><span>02</span><div><strong>解释问题与前提</strong><p>明确概念，也说明适用边界。</p></div></div><div class="aside-step"><span>03</span><div><strong>回到原文验证</strong><p>点击示例来源，阅读完整笔记。</p></div></div></section><section class="aside-note"><h3>试试这些示例</h3>${EXAMPLES.map(x=>`<button data-example="${x.id}" class="aside-question">${e(x.question)} ${icon('arrow')}</button>`).join('')}<a class="text-link" href="#/roadmap">真实 AI 什么时候接入？ ${icon('arrow')}</a></section></aside></div>`; }
export function practice(state) {
  const q=QUESTIONS[state.questionIndex]; const wrong=unresolved(); const choice=state.choice;const submitted=state.submitted;
  return `${heading('PRACTICE & REFLECT','把“看懂了”，变成“会用了”。','用三道固定练习检查理解。答题记录会保留在当前浏览器。')}${localNotice()}<div class="practice-layout"><section class="question-card"><div class="panel-heading">${badge('固定练习','green')}<span class="mono muted">${String(state.questionIndex+1).padStart(2,'0')} / 03</span></div><p class="section-kicker">${e(q.topic)}</p><h2>${e(q.prompt)}</h2><div class="options">${q.options.map((o,i)=>`<button class="option ${choice===i?'selected':''} ${submitted&&i===q.correct?'correct':''} ${submitted&&choice===i&&i!==q.correct?'incorrect':''}" data-choice="${i}" aria-pressed="${choice===i}" ${submitted?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${e(o)}</span>${submitted&&i===q.correct?icon('check'):''}</button>`).join('')}</div>${submitted?`<div class="explanation" role="status"><strong>${choice===q.correct?'回答正确，继续保持。':'再想一想，关键在这里。'}</strong><p>${e(q.explanation)}</p><button class="text-link" data-note="${q.sourceId}">回到资料 ${icon('arrow')}</button></div>`:''}<div class="question-footer"><span class="muted">答错的题会进入右侧复习列表</span>${submitted?`<button class="btn primary" data-action="next-question">${state.questionIndex===2?'再练一轮':'下一题'}${icon('arrow')}</button>`:`<button class="btn primary" data-action="submit-answer" ${choice===null?'disabled':''}>提交答案 ${icon('check')}</button>`}</div></section><aside><section class="panel"><div class="section-heading"><h2>待复习</h2>${badge(`${wrong.length} 题`,'amber')}</div>${wrong.length?wrong.map(a=>{const item=QUESTIONS.find(q=>q.id===a.questionId);return item?`<button class="review-row" data-review="${item.id}"><span class="file-icon">${icon('practice')}</span><span><strong>${e(item.topic)}</strong><small>再练一次，巩固这个知识点</small></span>${icon('arrow')}</button>`:''}).join(''):'<div class="empty-state compact">'+icon('check')+'<p>暂时没有待复习题目</p><small>提交练习后，错题会出现在这里。</small></div>'}</section><div class="aside-note"><p class="section-kicker">COMING NEXT</p><h3>让练习跟着你成长</h3><p>后续将基于课程资料生成练习，并使用真实答题记录安排复习。</p><a href="#/roadmap" class="text-link">查看学习闭环计划 ${icon('arrow')}</a></div></aside></div>`;
}
function phaseContent() { return `<div class="callout">${icon('route')}<div><strong>按阶段完成，每一步都能验收。</strong><p>周次按每周投入 8–12 小时估算，从启动真实功能开发起计。勾选项仅记录个人计划，不代表系统能力已经实现。</p></div></div><div class="phase-list">${PHASES.map((p,i)=>`<article class="phase-card ${i===0?'built':''}"><div class="phase-header"><span class="phase-index">${String(i).padStart(2,'0')}</span><div><p class="section-kicker">${p.subtitle}</p><h2>${p.name}</h2></div><div class="phase-meta">${badge(p.status,i===0?'green':'muted')}<span>${p.estimate}</span></div></div><div class="phase-content"><p>${p.deliverable}</p><ul class="task-list">${p.tasks.map(t=>`<li><label class="task-row"><input type="checkbox" data-task="${t.id}" ${t.built||store.completedTasks.includes(t.id)?'checked':''} ${t.built?'disabled':''}><span>${t.text}</span>${t.built?'<small>已实现</small>':''}</label></li>`).join('')}</ul><div class="acceptance"><div><strong>开始前需要</strong><p>${p.dependency}</p></div><div><strong>如何算完成</strong><p>${p.acceptance}</p></div></div></div></article>`).join('')}</div>`; }
function architecture() { return `<div class="callout">${icon('code')}<div><strong>先完成一个小闭环，再逐步替换内部模块。</strong><p>当前是无构建依赖的原生 JavaScript 原型。模型、检索、数据存储分别通过接口接入，保留页面与业务数据结构。</p></div></div><section class="panel architecture-panel"><p class="section-kicker">SYSTEM BLUEPRINT</p><h2>从界面到模型，各司其职。</h2><div class="architecture-flow"><div class="arch-node"><span class="badge green">当前已实现</span><h3>学习界面</h3><p>五个页面 · 资料 / 问答 / 练习</p><code>views.js + app.js</code></div><span class="arch-arrow">${icon('arrow')}</span><div class="arch-node"><span class="badge green">当前本地版</span><h3>业务与适配器</h3><p>记录管理 · 预置回答 · 本地存储</p><code>store.js + demo-provider.js</code></div><span class="arch-arrow">${icon('arrow')}</span><div class="arch-node planned"><span class="badge amber">后续接入</span><h3>服务端 AI 能力</h3><p>模型 API · 检索索引 · 持久化</p><code>HTTPS / server-side secrets</code></div></div></section><div class="dashboard-grid"><section class="panel"><h2>模块边界</h2><div class="boundary-list"><p><strong>ModelProvider</strong><span>统一模型输入、回答、用量与错误格式。</span></p><p><strong>Retriever</strong><span>返回资料片段 ID、原文、版本和相关度。</span></p><p><strong>Repository</strong><span>管理资料、会话和答题记录，替换本地存储。</span></p><p><strong>Evaluation</strong><span>在同一批问题上对比质量、速度和成本。</span></p></div></section><section class="panel"><h2>源码组织</h2><pre class="code-tree">dist/\n├── index.html       页面外壳\n├── styles.css       视觉与响应式\n├── js/\n│   ├── app.js       路由与交互\n│   ├── views.js     页面组件\n│   ├── data.js      课程样例与计划\n│   ├── store.js     本地数据仓库\n│   ├── demo-provider.js  问答适配器\n│   └── ui.js        安全输出与组件\n└── docs/            计划与架构文档</pre></section></div><section class="panel"><p class="section-kicker">GROW WITHOUT STARTING OVER</p><h2>后续怎么接，才不会推倒重来？</h2><p class="body-copy">保持资料 ID、来源片段、会话和答题记录的含义稳定。第一阶段先让页面调用服务端问答接口，第二阶段再替换检索实现。Python / PyTorch 研究服务独立部署，通过 HTTP 接入；Sites 服务层负责请求编排与数据权限。</p></section>`; }
function dataView() { return `<div class="entity-grid">${[{t:'Course',s:'课程',d:'id · title · description',p:'一门课程关联多份资料与知识点。'},{t:'Document / Chunk',s:'资料与片段',d:'id · courseId · content · version',p:'保留原文、版本、位置，支持可验证引用。'},{t:'Conversation / Message',s:'会话与问题',d:'id · question · answer · citations',p:'保存模型标识、用量与原文引用；当前为演示记录。'},{t:'Question / Attempt',s:'练习与答题',d:'id · questionId · option · correct',p:'当前固定题；后续关联知识点和审核状态。'},{t:'ReviewItem',s:'复习任务',d:'questionId · dueAt · status',p:'当前按最新答题结果显示错题，后续加入复习安排。'},{t:'EvalCase / EvalRun',s:'评测题与运行记录',d:'query · expectedSource · metrics',p:'后续用固定测试集衡量质量、耗时与成本。'}].map(x=>`<section class="entity-card"><span class="section-kicker">${x.t}</span><h2>${x.s}</h2><code>${x.d}</code><p>${x.p}</p></section>`).join('')}</div><section class="panel"><h2>数据与能力接入约定</h2><div class="boundary-list"><p><strong>当前原型</strong><span>只有浏览器本地存储，不跨设备同步。导出文件包含个人笔记和学习记录。</span></p><p><strong>真实 AI 接入</strong><span>模型密钥只放服务端；启用云端数据前建立用户隔离、删除与导出机制。</span></p><p><strong>资料处理</strong><span>优先支持文本和 Markdown，PDF、OCR 与图片识别在需求验证后逐步加入。</span></p><p><strong>效果验证</strong><span>先准备 20 个真实问题，覆盖可回答、无答案与资料冲突情形。每次修改保留对照结果。</span></p></div></section>`; }
export function roadmap(tab='plan') { return `${heading('BUILD SOMETHING THAT GROWS','一个项目，持续向深处生长。','从可用的学习空间，到可靠的 AI 系统，每个阶段都有明确交付。',`<a class="btn secondary" href="./docs/project-plan.md" download>${icon('download')}下载项目计划</a>`)}<div class="tabs" role="tablist" aria-label="项目规划">${[{id:'plan',t:'开发路线图'},{id:'architecture',t:'系统架构'},{id:'data',t:'数据与评测'}].map(t=>`<button class="tab ${tab===t.id?'active':''}" role="tab" aria-selected="${tab===t.id}" data-tab="${t.id}">${t.t}</button>`).join('')}</div><div class="tab-content" role="tabpanel">${tab==='architecture'?architecture():tab==='data'?dataView():phaseContent()}</div><div class="doc-grid"><a class="doc-card" href="./docs/project-plan.md" download>${icon('file')}<div><strong>完整项目计划</strong><p>范围、任务拆分、阶段依赖与验收标准</p></div>${icon('download')}</a><a class="doc-card" href="./docs/architecture.md" download>${icon('code')}<div><strong>架构设计说明</strong><p>数据实体、服务边界与后续接入方式</p></div>${icon('download')}</a></div>`; }
